package com.smartattendance.service;
import com.smartattendance.dto.*;import com.smartattendance.exception.ResourceNotFoundException;import com.smartattendance.model.Course;import com.smartattendance.repository.CourseRepository;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;
@Service
public class CourseService{private final CourseRepository repo;private final FacultyService faculty;public CourseService(CourseRepository repo,FacultyService faculty){this.repo=repo;this.faculty=faculty;}public Page<CourseResponse> search(String q,Pageable p){return(q==null||q.isBlank()?repo.findAll(p):repo.findByTitleContainingIgnoreCaseOrCodeContainingIgnoreCaseOrDepartmentContainingIgnoreCase(q,q,q,p)).map(this::toResponse);}public CourseResponse get(Long id){return toResponse(find(id));}public CourseResponse create(CourseRequest r){Course c=new Course();apply(c,r);return toResponse(repo.save(c));}public CourseResponse update(Long id,CourseRequest r){Course c=find(id);apply(c,r);return toResponse(repo.save(c));}public void delete(Long id){repo.delete(find(id));}public Course find(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Course",id));}private void apply(Course c,CourseRequest r){c.setCode(r.code());c.setTitle(r.title());c.setDepartment(r.department());c.setFaculty(faculty.find(r.facultyId()));}public CourseResponse toResponse(Course c){return new CourseResponse(c.getId(),c.getCode(),c.getTitle(),c.getDepartment(),c.getFaculty().getId(),c.getFaculty().getName());}}
